rules.declarations:
font-family: "Onest";
  font-style: normal;
  font-display: swap;
  font-weight: 100 900;
  src: url("/fonts/nostres-onest-cyrillic.woff2") format("woff2");
  unicode-range: U+0301,U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116;

font-family: "Onest";
  font-style: normal;
  font-display: swap;
  font-weight: 100 900;
  src: url("/fonts/nostres-onest-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;

font-family: "Source Serif 4";
  font-style: normal;
  font-display: swap;
  font-weight: 200 900;
  src: url("/fonts/nostres-source-serif-cyrillic.woff2") format("woff2");
  unicode-range: U+0301,U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116;

font-family: "Source Serif 4";
  font-style: normal;
  font-display: swap;
  font-weight: 200 900;
  src: url("/fonts/nostres-source-serif-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;

--font-ui: "Onest", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-editorial: "Source Serif 4", Georgia, "Times New Roman", serif;
  --ink: #17263f;
  --ink-2: #30415e;
  --paper: #ffffff;
  --canvas: #f1f4f7;
  --coral: #ff735f;
  --coral-soft: #ffe1dc;
  --blue: #b9d9f4;
  --blue-soft: #e0f0fb;
  --lilac: #d8d0ee;
  --mint: #cae3d8;
  --sand: #e7d8b9;
  --line: rgba(23, 38, 63, 0.16);
  --shadow: 0 20px 55px rgba(23, 38, 63, 0.11);

margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: 16px;
  line-height: 1.55;
  text-rendering: optimizeLegibility;
  font-synthesis: none;

content: "";
  position: fixed;
  z-index: -1;
  inset: 0;
  opacity: 0.28;
  background-image: radial-gradient(circle at 1px 1px, rgba(23, 38, 63, 0.14) 1px, transparent 0);
  background-size: 26px 26px;
  pointer-events: none;

position: relative;
  z-index: 5;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  width: min(1240px, calc(100% - 48px));
  min-height: 80px;
  margin: 0 auto;
  border-bottom: 1px solid var(--line);

display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  background: var(--ink);
  color: white;
  border-radius: 50% 50% 50% 18%;
  font-family: var(--font-editorial);
  font-size: 20px;

position: relative;
  width: min(1240px, calc(100% - 48px));
  margin: 0 auto;
  padding: 68px 0 78px;

content: "BERLIN";
  position: absolute;
  z-index: -1;
  right: 0;
  top: 33px;
  color: rgba(23, 38, 63, 0.045);
  font-family: var(--font-editorial);
  font-size: min(14vw, 180px);
  letter-spacing: -0.045em;
  pointer-events: none;

display: grid;
  grid-template-columns: 1.2fr 0.72fr;
  align-items: end;
  gap: 70px;
  margin-bottom: 38px;

margin-bottom: 12px;
  color: #a34741;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.12em;
  text-transform: uppercase;

max-width: 520px;
  margin-bottom: 4px;
  color: var(--ink-2);
  font-size: 17px;
  line-height: 1.7;

overflow: hidden;
  background: var(--paper);
  border: 1px solid rgba(23, 38, 63, 0.09);
  border-radius: 22px;
  box-shadow: var(--shadow);

display: block;
  margin-bottom: 6px;
  color: #5b6474;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.12em;
  text-transform: uppercase;

display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
  min-height: 54px;
  padding: 13px 18px;
  background: var(--coral);
  color: #201d24;
  border: 0;
  border-radius: 12px;
  font-weight: 850;
  cursor: pointer;
  transition: transform 160ms ease, background 160ms ease;

display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--line);

display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 20px;
  background: var(--ink);
  color: #dce5f0;
  font-size: 11px;

display: grid;
  grid-template-columns: 1fr 400px;
  gap: 56px;
  align-items: end;
  margin-bottom: 32px;

padding: 8px 12px;
  background: rgba(255,255,255,0.35);
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 11px;
  cursor: pointer;
  transition: background 150ms ease, color 150ms ease;

display: flex;
  min-height: 330px;
  flex-direction: column;
  padding: 25px;
  border: 1px solid rgba(23, 38, 63, 0.08);
  border-radius: 18px;
  transition: transform 180ms ease, box-shadow 180ms ease;

display: flex;
  align-items: center;
  gap: 8px;
  width: max-content;
  margin-top: 18px;
  padding: 0;
  background: transparent;
  border: 0;
  border-bottom: 1px solid transparent;
  font-size: 12px;
  font-weight: 850;
  cursor: pointer;

grid-column: 1 / -1;
  padding: 60px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  text-align: center;

display: grid;
  grid-template-columns: 1fr 24px;
  align-items: center;
  gap: 13px;
  min-height: 96px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--line);
  transition: background 160ms ease;

display: grid;
  grid-template-columns: 70px 1fr;
  align-items: center;
  gap: 25px;
  max-width: 900px;
  margin: 44px auto 0;
  padding: 25px 28px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow: 0 12px 34px rgba(23,38,63,0.06);

display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  margin-top: 18px;
  padding: 12px 14px;
  background: transparent;
  border: 1px solid var(--ink);
  border-radius: 10px;
  font-size: 12px;
  font-weight: 850;
  cursor: pointer;
  transition: background 160ms ease, color 160ms ease;

display: grid;
  grid-template-columns: minmax(0, 760px) auto;
  align-items: center;
  gap: 40px;
  width: min(1240px, calc(100% - 48px));
  margin: 0 auto 92px;
  padding: 34px;
  background: var(--ink);
  color: white;
  border-radius: 20px;

display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 13px;
  font-weight: 850;

min-height: 40px;
  padding: 0 12px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--ink);
  font: inherit;
  font-size: 13px;
  font-weight: 850;
  cursor: pointer;

grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto auto;
    row-gap: 8px;
    padding-block: 10px;

display: inline-flex;
    grid-column: 1;
    grid-row: 2;
    justify-self: start;
    align-items: center;
    min-height: 36px;
